create extension if not exists pgcrypto;
create table public.profiles (id uuid primary key references auth.users(id) on delete cascade, display_name text not null default '', role text not null default 'cai' check(role in ('admin','cai','ketoan')), created_at timestamptz default now());
create table public.projects (id uuid primary key default gen_random_uuid(), name text not null, site_address text, status text default 'active', created_at timestamptz default now());
create table public.workers (id uuid primary key default gen_random_uuid(), full_name text not null, phone text, position text not null default 'Phụ' check(position in ('Cai','Thợ','Phụ')), id_number text, address text, bank_name text, bank_account text, bank_owner text, daily_rate numeric(12,2) default 0, active boolean default true, created_at timestamptz default now());
create table public.project_workers (project_id uuid references public.projects(id) on delete cascade, worker_id uuid references public.workers(id) on delete cascade, assigned_at timestamptz default now(), primary key(project_id,worker_id));
create table public.attendance (id uuid primary key default gen_random_uuid(), worker_id uuid references public.workers(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, work_date date not null, status text not null check(status in ('present','absent','leave')), work_units numeric(3,1) default 0 check(work_units in (0,0.5,1)), overtime_hours numeric(5,2) default 0, note text, recorded_by uuid references auth.users(id), created_at timestamptz default now(), unique(worker_id,project_id,work_date));
create table public.advances (id uuid primary key default gen_random_uuid(), worker_id uuid references public.workers(id) on delete cascade, project_id uuid references public.projects(id) on delete set null, amount numeric(12,2) not null check(amount>0), advance_date date default current_date, note text, created_by uuid references auth.users(id), created_at timestamptz default now());
create or replace function public.user_role() returns text language sql stable security definer set search_path=public as $$ select role from public.profiles where id=auth.uid() $$;
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.user_role()='admin',false) $$;
create or replace function public.is_staff() returns boolean language sql stable security definer set search_path=public as $$ select coalesce(public.user_role() in ('admin','cai','ketoan'),false) $$;
-- Enable RLS and default deny for anonymous access.
alter table public.profiles enable row level security; alter table public.projects enable row level security; alter table public.workers enable row level security; alter table public.project_workers enable row level security; alter table public.attendance enable row level security; alter table public.advances enable row level security;
create policy "profile own or admin read" on public.profiles for select to authenticated using (id=auth.uid() or is_admin()); create policy "admin profiles write" on public.profiles for all to authenticated using (is_admin()) with check (is_admin());
create policy "staff projects read" on public.projects for select to authenticated using (is_staff()); create policy "admin projects write" on public.projects for all to authenticated using (is_admin()) with check (is_admin());
create policy "staff workers read" on public.workers for select to authenticated using (is_staff()); create policy "admin workers write" on public.workers for all to authenticated using (is_admin()) with check (is_admin());
create policy "staff project-worker read" on public.project_workers for select to authenticated using (is_staff()); create policy "admin project-worker write" on public.project_workers for all to authenticated using (is_admin()) with check (is_admin());
create policy "staff attendance read" on public.attendance for select to authenticated using (is_staff()); create policy "admin cai attendance write" on public.attendance for all to authenticated using (public.user_role() in ('admin','cai')) with check (public.user_role() in ('admin','cai'));
create policy "admin accountant advances read" on public.advances for select to authenticated using (public.user_role() in ('admin','ketoan')); create policy "admin accountant advances write" on public.advances for all to authenticated using (public.user_role() in ('admin','ketoan')) with check (public.user_role() in ('admin','ketoan'));
